<?php
declare(strict_types=1);
if(session_status()===PHP_SESSION_NONE)session_start();
require 'scripts/connector.php';
require_once 'scripts/module_completion_helpers.php';
$systemname=$systemname??'';
if(!isset($conn)||!($conn instanceof mysqli)){echo '<div class="alert alert-danger">Database connection not available.</div>';return;}
if(!function_exists('h')){function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}}
function sdate($v,$fmt='D, d M Y h:i a'):string{return $v&&strtotime((string)$v)!==false?date($fmt,strtotime((string)$v)):'-';}
$cx=(int)($_GET['course']??0);$uid=(string)($_SESSION[$systemname.'leido']??'');$role=(string)($_SESSION[$systemname.'letype']??'');
if($cx<=0||$uid===''||$role!=='afgezt'){echo '<div class="alert alert-danger">Access denied.</div>';return;}
$s=$conn->prepare("SELECT cr.intake,COALESCE(NULLIF(cr.class_mode,''),'both') class_mode,COALESCE(cr.branch_id,i.branch_id,0) branch_id FROM course_registration cr LEFT JOIN intakes i ON i.id=cr.intake WHERE cr.user_id=? AND cr.course_id=? LIMIT 1");$s->bind_param('si',$uid,$cx);$s->execute();$reg=$s->get_result()->fetch_assoc();$s->close();if(!$reg){echo '<div class="alert alert-danger">Invalid course selection.</div>';return;}
$intake=(int)$reg['intake'];$class=(string)$reg['class_mode'];$branch=(int)$reg['branch_id'];
$s=$conn->prepare('SELECT * FROM courses WHERE id=? LIMIT 1');$s->bind_param('i',$cx);$s->execute();$course=$s->get_result()->fetch_assoc();$s->close();
$mods=[];$s=$conn->prepare('SELECT * FROM course_unit WHERE course_id=? ORDER BY order_number,id');$s->bind_param('i',$cx);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$mods[]=$x;$s->close();
?>
