<?php $previousComplete=true; foreach($mods as $mi=>$m):$mid=(int)$m['id']; $locked=(($m['access_mode']??'immediate')==='after_previous' && $mi>0 && !$previousComplete); $completion=course_module_completion($conn,$uid,$mid,$intake); ?>
<?php if($locked): ?><section style="margin-bottom:24px"><div class="page-heading"><div><h2><?php echo h($m['name']);?></h2><div class="heading-meta"><span class="meta-pill"><?php echo $completion['done'];?>/<?php echo $completion['required'];?> required items completed</span><?php if($completion['complete']):?><span class="meta-pill"><i class="fas fa-check-circle"></i> Module completed</span><?php endif;?></div></div></div><div class="empty"><i class="fas fa-lock"></i><p>Complete the previous module to unlock this module.</p></div></section><?php $previousComplete=false; continue; endif; ?>
<?php
$topics=[];$s=$conn->prepare("SELECT t.*,EXISTS(SELECT 1 FROM topic_completion tc WHERE tc.topic_id=t.id AND tc.user_id=?) completed FROM course_topics t WHERE t.course_unit_id=? AND COALESCE(t.intake_id,0) IN (0,?) AND t.status='active' AND (t.class_mode='both' OR t.class_mode=? OR ?='both') ORDER BY t.order_number,t.id");$s->bind_param('siiss',$uid,$mid,$intake,$class,$class);$s->execute();$rr=$s->get_result();while($x=$rr->fetch_assoc())$topics[]=$x;$s->close();
$assign=[];$s=$conn->prepare("SELECT a.*,(SELECT COUNT(*) FROM handed_in hi WHERE hi.assignment_id=a.id AND hi.user_id=?) attempt_count,(SELECT hi.status FROM handed_in hi WHERE hi.assignment_id=a.id AND hi.user_id=? ORDER BY hi.id DESC LIMIT 1) latest_status,(SELECT hi.finalmarks FROM handed_in hi WHERE hi.assignment_id=a.id AND hi.user_id=? ORDER BY hi.id DESC LIMIT 1) latest_grade,(SELECT hi.feedback FROM handed_in hi WHERE hi.assignment_id=a.id AND hi.user_id=? ORDER BY hi.id DESC LIMIT 1) latest_feedback FROM assignments a JOIN intakes i ON i.id=a.intake WHERE a.course_unit=? AND a.intake=? AND COALESCE(a.status,'active')='active' AND COALESCE(a.dummy,'no')='no' AND COALESCE(i.branch_id,0)=? AND (a.class_mode='both' OR a.class_mode=? OR ?='both') ORDER BY a.id DESC");$s->bind_param('ssssiiiss',$uid,$uid,$uid,$uid,$mid,$intake,$branch,$class,$class);$s->execute();$rr=$s->get_result();while($x=$rr->fetch_assoc())$assign[]=$x;$s->close();
$quizzes=[];$s=$conn->prepare("SELECT q.*,(SELECT COUNT(*) FROM quiz_questions qq WHERE qq.quiz_id=q.id) question_count FROM module_quizzes q WHERE q.course_unit_id=? AND COALESCE(q.intake_id,0) IN (0,?) AND q.status='active' AND (q.class_mode='both' OR q.class_mode=? OR ?='both') ORDER BY q.id DESC");$s->bind_param('iiss',$mid,$intake,$class,$class);$s->execute();$rr=$s->get_result();while($x=$rr->fetch_assoc())$quizzes[]=$x;$s->close();?>
<section style="margin-bottom:24px"><div class="page-heading"><div><h2><?php echo h($m['name']);?></h2><div class="heading-meta"><span class="meta-pill"><?php echo $completion['done'];?>/<?php echo $completion['required'];?> required items completed</span><?php if($completion['complete']):?><span class="meta-pill"><i class="fas fa-check-circle"></i> Module completed</span><?php endif;?></div></div></div><div class="learn-tabs"><button class="learn-tab active" onclick="lSwitch(<?php echo $mi;?>,'topics',this)">Topics <?php echo count($topics);?></button><button class="learn-tab" onclick="lSwitch(<?php echo $mi;?>,'assign',this)">Assignments <?php echo count($assign);?></button><button class="learn-tab" onclick="lSwitch(<?php echo $mi;?>,'quiz',this)">Quizzes <?php echo count($quizzes);?></button></div>
