<div class="learn-panel" id="lp-<?php echo $mi;?>-assign"><?php if(!$assign):?><div class="empty"><p>No assignments available.</p></div><?php endif;?><?php foreach($assign as $a):$aid=(int)$a['id'];$resources=[];$s=$conn->prepare('SELECT * FROM assignment_resources WHERE assignment_id=? ORDER BY id');$s->bind_param('i',$aid);$s->execute();$ar=$s->get_result();while($x=$ar->fetch_assoc())$resources[]=$x;$s->close();?><div class="assign-card"><div class="t-head"><div><div class="t-title"><?php echo h($a['title']);?></div><div class="t-meta"><?php echo h((string)$a['marks']);?> points · Due <?php echo h(sdate($a['date_due']));?> · Attempts <?php echo (int)$a['attempt_count'];?>/<?php echo (int)($a['max_attempts']??1);?></div><div class="t-meta"><?php echo h($a['short_message']);?></div><?php if(!empty($a['latest_status'])):?><div class="t-meta">Status: <strong><?php echo h(ucfirst($a['latest_status']));?></strong><?php if($a['latest_grade']!==null&&$a['latest_grade']!==''):?> · Grade: <strong><?php echo h((string)$a['latest_grade']);?>/<?php echo h((string)$a['marks']);?></strong><?php endif;?></div><?php if(!empty($a['latest_feedback'])):?><div class="t-meta">Feedback: <?php echo h($a['latest_feedback']);?></div><?php endif;?><?php endif;?></div><button class="btnx gold" onclick="openSubmit(<?php echo $aid;?>,<?php echo h(json_encode($a['title']));?>,<?php echo h(json_encode($a['submission_type']??'file'));?>)">Submit</button></div><?php if($resources):?><div class="materials"><?php foreach($resources as $res):?><div class="mat"><div class="t-title" style="font-size:.83rem"><?php echo h($res['title']);?></div><?php if($res['resource_type']==='file'):?><a class="btnx soft" href="course_materials/<?php echo rawurlencode($res['document']);?>" target="_blank">Open resource</a><?php elseif($res['resource_type']==='link'):?><a class="btnx soft" href="<?php echo h($res['resource_url']);?>" target="_blank">Open link</a><?php else:?><div class="t-meta" style="white-space:pre-wrap"><?php echo h($res['resource_text']);?></div><?php endif;?></div><?php endforeach;?></div><?php endif;?></div><?php endforeach;?></div>
<div class="learn-panel" id="lp-<?php echo $mi;?>-quiz"><?php if(!$quizzes):?><div class="empty"><p>No quizzes available.</p></div><?php endif;?><?php foreach($quizzes as $q):?><div class="quiz-card"><div class="t-title"><?php echo h($q['title']);?></div><div class="t-meta"><?php echo (int)$q['question_count'];?> questions · <?php echo h((string)$q['total_points']);?> points · Pass <?php echo h((string)$q['passing_score']);?>% · <?php echo h(sdate($q['deadline']));?></div><div style="margin-top:8px"><a class="btnx primary" href="?view=take_quiz&quiz_id=<?php echo (int)$q['id'];?>">Take Quiz</a></div></div><?php endforeach;?></div></section><?php $previousComplete=$completion['complete']; endforeach;?>
