<div class="modal-overlay" id="submitModal"><div class="modal-box"><form id="submitForm" enctype="multipart/form-data"><div class="modal-head"><strong>Submit Assignment — <span id="subTitle"></span></strong><button type="button" class="btnx soft" onclick="closeM()">×</button></div><div class="modal-body"><input type="hidden" name="assignment_id" id="subAssignment"><div class="field"><label>Submission Type</label><select name="submission_type" id="subType" onchange="toggleSubFields()"></select></div><div class="field" id="subFile"><label>Upload File</label><input type="file" name="submission_file"></div><div class="field" id="subText" style="display:none"><label>Text Response</label><textarea name="text_response" rows="8"></textarea></div><div class="field" id="subUrl" style="display:none"><label>Submission URL</label><input name="submission_url" placeholder="https://..."></div></div><div class="modal-foot"><button type="button" class="btnx soft" onclick="closeM()">Cancel</button><button class="btnx gold">Submit Assignment</button></div></form></div></div>
<script>
function lSwitch(i,k,b){const sec=b.closest('section');sec.querySelectorAll('.learn-panel').forEach(x=>x.classList.remove('active'));sec.querySelectorAll('.learn-tab').forEach(x=>x.classList.remove('active'));document.getElementById('lp-'+i+'-'+k).classList.add('active');b.classList.add('active')}
async function toggleTopic(id,complete){const f=new FormData();f.append('topic_id',id);f.append('complete',complete);const r=await fetch('scripts/toggle_topic_completion.php',{method:'POST',body:f});const j=await r.json();alert(j.message);if(j.success)location.reload()}
function openSubmit(id,title,allowed){document.getElementById('subAssignment').value=id;document.getElementById('subTitle').textContent=title;const s=document.getElementById('subType');s.innerHTML='';const map={file:['file'],text:['text'],link:['link'],file_text:['file','text'],any:['file','text','link']};(map[allowed]||['file']).forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v==='file'?'File Upload':v==='text'?'Text Response':'Link';s.appendChild(o)});toggleSubFields();document.getElementById('submitModal').classList.add('is-open')}
function closeM(){document.getElementById('submitModal').classList.remove('is-open')}
function toggleSubFields(){const t=document.getElementById('subType').value;document.getElementById('subFile').style.display=t==='file'?'':'none';document.getElementById('subText').style.display=t==='text'?'':'none';document.getElementById('subUrl').style.display=t==='link'?'':'none'}
document.getElementById('submitForm').addEventListener('submit',async e=>{e.preventDefault();const r=await fetch('scripts/submit_assignment_v2.php',{method:'POST',body:new FormData(e.currentTarget)});const j=await r.json();alert(j.message);if(j.success)location.reload()});
</script>
